import{_ as t,c as a,o as r,ae as i}from"./chunks/framework.DI6M9D4h.js";const o="/assets/prospector-parts-1.BkhfX7iE.jpg",s="/assets/prospector-assembly-1.DWckwSpk.jpg",l="/assets/prospector-assembly-2.Drf0nGg_.jpg",n="/assets/prospector-assembly-3.C2so_qzq.jpg",p="/assets/prospector-assembly-4.KOaUb5Ck.jpg",d="/assets/prospector-assembly-5.DFEbUsXp.jpg",h="/assets/prospector-assembly-6.Bnix52Da.jpg",c="/assets/prospector_wiring-1.i04Sp0BX.png",m="/assets/prospector-assembly-8.D58tknFJ.jpg",P=JSON.parse('{"title":"Prospector ZMK Dongle - Build Guide","description":"","frontmatter":{"outline":[2,4]},"headers":[],"relativePath":"build-guides/prospector/index.md","filePath":"build-guides/prospector/index.md","lastUpdated":1755193898000}'),u={name:"build-guides/prospector/index.md"};function g(b,e,f,w,y,_){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="prospector-zmk-dongle-build-guide" tabindex="-1">Prospector ZMK Dongle - Build Guide <a class="header-anchor" href="#prospector-zmk-dongle-build-guide" aria-label="Permalink to &quot;Prospector ZMK Dongle - Build Guide&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This build guide is in progress. Missing parts:</p><ul><li>Images of the transparent light guide</li><li>Image of Xiao mounted in to the rear cap</li><li>Customize the firmware</li></ul></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Do not press the reset button on the rear cap unless an XIAO is installed (doing so will break it).</p></div><h2 id="parts-included-in-the-kit" tabindex="-1">Parts included in the Kit <a class="header-anchor" href="#parts-included-in-the-kit" aria-label="Permalink to &quot;Parts included in the Kit&quot;">​</a></h2><p><img src="'+o+'" alt="Prospector Kit Parts" loading="lazy"></p><table tabindex="0"><thead><tr><th>Part Name</th><th>Count</th></tr></thead><tbody><tr><td>3D-printed case (display mount, main body, rear cap, light guid cap)</td><td>1</td></tr><tr><td>Seeed Studio XIAO nRF52840</td><td>1</td></tr><tr><td>Waveshare 1.69inch Round LCD Display Module with Touch</td><td>1</td></tr><tr><td>Adafruit APDS9960 Proximity, Light, RGB, and Gesture Sensor</td><td>1</td></tr><tr><td>M2x6 pan/wafer head screws</td><td>4</td></tr><tr><td>M2.5x4 pan/wafer head screws</td><td>4</td></tr></tbody></table><h3 id="other-required-items" tabindex="-1">Other required items <a class="header-anchor" href="#other-required-items" aria-label="Permalink to &quot;Other required items&quot;">​</a></h3><ul><li>1/16 hexagon screwdriver (1.5 metric will not work properly) for M2.5 screws</li><li>0.05&quot; or 1.3mm hexagon screwdriver for M2 screws</li><li>Soldering iron with adjustable temperature (320°C)</li><li>Solder (i use Sn99.3Cu0.7 0.5mm/0.02inch)</li><li>Flux</li><li>Tip cleaner (wet sponge or brass wool)</li><li>Side cutters/flush cutters</li></ul><h2 id="assembly" tabindex="-1">Assembly <a class="header-anchor" href="#assembly" aria-label="Permalink to &quot;Assembly&quot;">​</a></h2><p>A build guide by Carrefinho is available <a href="./[https://](https://raw.githubusercontent.com/carrefinho/prospector/main/docs/prospector_assembly_manual.jpg).html">here</a>.</p><h3 id="prepare-the-display-cable" tabindex="-1">Prepare the Display cable <a class="header-anchor" href="#prepare-the-display-cable" aria-label="Permalink to &quot;Prepare the Display cable&quot;">​</a></h3><p>You need some extra wires for the light sensor and the last 4 wires on the display cable are not connected later. So remove these and keep them for later. Use the tweezers to lift the platic and pull out the wire (only the green, orange, yellow and blue wire).</p><p><img src="'+s+'" alt="" loading="lazy"></p><h3 id="mount-the-display" tabindex="-1">Mount the display <a class="header-anchor" href="#mount-the-display" aria-label="Permalink to &quot;Mount the display&quot;">​</a></h3><p>Connect the display cable.</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>Attach the display to the display mount. Use 4x M2x6 screws to mount it to the main body.</p><p>Keep attention to the orientation of the display and it&#39;s cable.</p><p><img src="'+n+'" alt="" loading="lazy"></p><h3 id="solder-wires" tabindex="-1">Solder wires <a class="header-anchor" href="#solder-wires" aria-label="Permalink to &quot;Solder wires&quot;">​</a></h3><p>Solder the wires to the light sensor like on the picture. Use 3 from the previouse saved wires and cut a piece of red and black wire from the display cable approximately 5 cm long.</p><p>Cover the green power LED on the light sensor PCB with tape to prevent it from affecting the light sensor. Refer to the <a href="#wiring-diagram">wiring diagram</a> to identify the correct position.</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>Turn the main body up side down and put the transparent light guide in the hole of the main body.</p><p>Place the light sensor in the main body (SMD parts facing to the light guide) and secure it with 2x M2.5x4 screws.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not overtighten the screws, or the plastic threads will break!</p></div><p><img src="'+d+'" alt="" loading="lazy"></p><p><img src="'+h+'" alt="" loading="lazy"></p><p>Solder all wire to the XIAO. Below you find the wiring diagram.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Please pay attention that the three colored cable from the light sensor board have different colors in the wiring diagram.</p><p>Also the blue and purple wires are easy to confuse.</p></div><h4 id="wiring-diagram" tabindex="-1">Wiring diagram <a class="header-anchor" href="#wiring-diagram" aria-label="Permalink to &quot;Wiring diagram&quot;">​</a></h4><p><img src="'+c+'" alt="" loading="lazy"><em>Source: <a href="https://github.com/carrefinho/prospector/blob/main/docs/prospector_assembly_manual.jpg" target="_blank" rel="noreferrer">Prospector docs by carrefinho</a></em></p><p>Cut off the protruding pins with side cutters.</p><h3 id="complet-the-case" tabindex="-1">Complet the case <a class="header-anchor" href="#complet-the-case" aria-label="Permalink to &quot;Complet the case&quot;">​</a></h3><p>Use the remaining 2x M2.5x4 screws to secure the rear cap to the main body.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not overtighten the screws, or the plastic threads will break!</p></div><p><img src="'+m+'" alt="" loading="lazy"></p><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><h3 id="install-firmware" tabindex="-1">Install firmware <a class="header-anchor" href="#install-firmware" aria-label="Permalink to &quot;Install firmware&quot;">​</a></h3><p>Plug in the USB-C to the Prospector. A green led light should be visible at the top and the display blinks black.</p><p>Double press the reset switch at the bottom of the Prospector case. A storage should appear in you file browser.</p><p>Drag the <code>forager_dongle_prospector.uf2</code> firmware file on it and wait until the storage is automatic ejected.</p><p>The Prospector should display the standard screen as below.</p><ul><li>[ ] image from screen</li></ul><p>First factory resest if allready paired with a computer.</p><h3 id="customize-the-firmware" tabindex="-1">Customize the firmware <a class="header-anchor" href="#customize-the-firmware" aria-label="Permalink to &quot;Customize the firmware&quot;">​</a></h3><p>[todo]</p>',47)])])}const x=t(u,[["render",g]]);export{P as __pageData,x as default};
